import glob, os
D = os.path.join(os.path.dirname(os.path.abspath(__file__)), "data")
WHO = {"U":U,"T":T,"N":N}; LVL = {"O":OFF,"2":TWO,"1":ONE,"X":CONF}
extra_src = []
for f in sorted(glob.glob(D+"/*.txt")):
    dev = brand = None
    for ln in open(f, encoding="utf-8"):
        ln = ln.rstrip("\n")
        if not ln.strip(): continue
        if ln.startswith("@"):
            dev, brand = [x.strip() for x in ln[1:].split("|")]; continue
        if ln.startswith("#"):
            n,u = ln[1:].split("|",1); extra_src.append((n.strip(),u.strip())); continue
        p = [x.strip() for x in ln.split("|")]
        assert len(p) in (6,7,8), (f, ln)
        code,mean,cause,who,lvl,src = p[:6]
