SAM_C = {"P2","t5","t9","E2","G6","E161","E180","E181","E182","E201","E704"} | _r("E",190,193) | _r("E",210,215) | _r("E",256,258) | _r("E",262,268) | {"E271"} | _r("E",276,278) | {"E401","E402","E405","E406","E408","E409","E411","E412"} | _r("E",413,415) | {"E417","E418","E420","E421","E423","E424","E426","E427"} | _r("E",428,430)
DAI_C = {"AF","AH","EC","EF","HC","HF","HJ","JE","JH","H1","M1","M8","MA","MC","P2","P8","P9","PA","PC","PE","PH","UE","U9","UH"}
def _central(row):
    dev,brand,code = row[0],row[1],row[3]
    if dev != AC: return False
    if brand == "ميتسوبيشي": return code.isdigit() and len(code) == 4
    if brand == "سامسونج": return code in SAM_C
    if brand == "دايكن": return code in DAI_C
    return False

