def _drive(r):
    r = tuple(r) + ("",)*(11-len(r))
    if r[0] != CAR or r[10]: return r
    txt = r[4]+" "+r[5]
    if any(k in txt for k in _STOPK): d = D_STOP
    elif r[6] == N: d = D_OK
    elif r[6] == U: d = D_FIX
    else: d = D_CARE
    return r[:10]+(d,)
